"""Deterministic automaton engine used to publish canonical policy images.

A DFA is stored in a compact, iteration friendly form::

    trans   list of dicts, one per state, mapping a service name to a target
    finals  set of accepting states
    start   index of the initial state

Every routine here is iterative.  The supplied FAdo release implements Moore's
refinement recursively, which overflows the interpreter stack on the long
chains that a policy language allows, so the refinement below is Hopcroft's.
"""

#: Target of a transition that can never be taken.
DENY = 4294967295


class Dfa(object):
    """A deterministic automaton over service names."""

    __slots__ = ('trans', 'finals', 'start')

    def __init__(self, trans, finals, start=0):
        self.trans = trans
        self.finals = finals
        self.start = start

    @property
    def size(self):
        return len(self.trans)


def complete(dfa, sigma):
    """Return a complete copy of *dfa* over *sigma* using a silent sink."""
    sink = dfa.size
    trans = []
    for row in dfa.trans:
        trans.append(dict((c, row.get(c, sink)) for c in sigma))
    trans.append(dict((c, sink) for c in sigma))
    return Dfa(trans, set(dfa.finals), dfa.start)


def complement(dfa, sigma):
    """Return the complement of *dfa* relative to ``sigma`` star."""
    done = complete(dfa, sigma)
    return Dfa(done.trans, set(range(done.size)) - done.finals, done.start)


def union(dfas, sigma):
    """Determinise the non deterministic automaton formed by *dfas*.

    The result accepts the union of the given languages.  Only reachable
    subsets are built, which keeps a union of many exact paths linear in the
    number of services that occur in them.
    """
    if not dfas:
        return Dfa([{}], set(), 0)
    offsets = []
    total = 0
    for dfa in dfas:
        offsets.append(total)
        total += dfa.size
    owner = [0] * total
    local = [0] * total
    for index, dfa in enumerate(dfas):
        base = offsets[index]
        for state in range(dfa.size):
            owner[base + state] = index
            local[base + state] = state
    start = frozenset(offsets[index] + dfa.start for index, dfa in enumerate(dfas))
    index = {start: 0}
    trans = [{}]
    finals = set()
    queue = [start]
    head = 0
    while head < len(queue):
        current = queue[head]
        head += 1
        state = index[current]
        for gid in current:
            dfa = dfas[owner[gid]]
            if local[gid] in dfa.finals:
                finals.add(state)
                break
        row = {}
        for symbol in sigma:
            following = set()
            for gid in current:
                dfa = dfas[owner[gid]]
                target = dfa.trans[local[gid]].get(symbol)
                if target is not None:
                    following.add(offsets[owner[gid]] + target)
            key = frozenset(following)
            target = index.get(key)
            if target is None:
                target = len(queue)
                index[key] = target
                queue.append(key)
                trans.append({})
            row[symbol] = target
        trans[state] = row
    return Dfa(trans, finals, 0)


def product(dfas, acceptor, sigma):
    """Product of complete DFAs.

    *acceptor* maps a tuple of accept flags, one per automaton, to the
    acceptance of the product state.
    """
    if not dfas:
        return Dfa([dict((c, 0) for c in sigma)], set(), 0)
    start = tuple(dfa.start for dfa in dfas)
    index = {start: 0}
    trans = [{}]
    finals = set()
    queue = [start]
    head = 0
    while head < len(queue):
        current = queue[head]
        head += 1
        state = index[current]
        flags = tuple(1 if current[i] in dfas[i].finals else 0
                      for i in range(len(dfas)))
        if acceptor(flags):
            finals.add(state)
        row = {}
        for symbol in sigma:
            key = tuple(dfas[i].trans[current[i]][symbol] for i in range(len(dfas)))
            target = index.get(key)
            if target is None:
                target = len(queue)
                index[key] = target
                queue.append(key)
                trans.append({})
            row[symbol] = target
        trans[state] = row
    return Dfa(trans, finals, 0)


def intersect(left, right, sigma):
    """Intersection of two complete DFAs."""
    return product([left, right],
                   lambda flags: bool(flags[0]) and bool(flags[1]),
                   sigma)


def minimize(dfa, sigma):
    """Return the minimal equivalent DFA (Hopcroft's partition refinement)."""
    trans = dfa.trans
    finals = set(dfa.finals)
    start = dfa.start

    # Drop states that cannot be reached from the initial state.
    seen = set([start])
    stack = [start]
    while stack:
        state = stack.pop()
        row = trans[state]
        for symbol in sigma:
            target = row.get(symbol)
            if target is not None and target not in seen:
                seen.add(target)
                stack.append(target)
    if len(seen) != len(trans):
        order = sorted(seen)
        remap = dict((state, index) for index, state in enumerate(order))
        trans = [dict((c, remap[trans[state][c]]) for c in sigma if c in trans[state])
                 for state in order]
        finals = set(remap[state] for state in finals if state in seen)
        start = remap[start]

    count = len(trans)

    # Inverse transitions, one table per symbol.
    inverse = []
    for symbol in sigma:
        table = {}
        for state, row in enumerate(trans):
            target = row.get(symbol)
            if target is not None:
                bucket = table.get(target)
                if bucket is None:
                    table[target] = [state]
                else:
                    bucket.append(state)
        inverse.append(table)

    # Initial partition: accepting and rejecting states.
    blocks = []
    block_of = [0] * count
    accepting = finals
    rejecting = set(range(count)) - accepting
    if accepting:
        blocks.append(accepting)
    if rejecting:
        blocks.append(rejecting)
    for index, block in enumerate(blocks):
        for state in block:
            block_of[state] = index
    if len(blocks) < 2:
        return Dfa([dict((c, 0) for c in sigma)],
                   set([0]) if accepting else set(), 0)

    work = set([0 if len(blocks[0]) <= len(blocks[1]) else 1])
    while work:
        index = work.pop()
        splitter = blocks[index]
        for position, symbol in enumerate(sigma):
            table = inverse[position]
            touched = {}
            for target in splitter:
                bucket = table.get(target)
                if bucket:
                    for state in bucket:
                        owner = block_of[state]
                        group = touched.get(owner)
                        if group is None:
                            touched[owner] = [state]
                        else:
                            group.append(state)
            for owner, members in touched.items():
                block = blocks[owner]
                if len(members) == len(block):
                    continue
                inside = set(members)
                outside = block - inside
                # The larger half keeps the index, the smaller half becomes a
                # new block; only the smaller half has to be scheduled.
                if len(inside) >= len(outside):
                    blocks[owner] = inside
                    fresh = len(blocks)
                    blocks.append(outside)
                    for state in inside:
                        block_of[state] = owner
                    for state in outside:
                        block_of[state] = fresh
                else:
                    blocks[owner] = outside
                    fresh = len(blocks)
                    blocks.append(inside)
                    for state in outside:
                        block_of[state] = owner
                    for state in inside:
                        block_of[state] = fresh
                work.add(fresh)

    # Quotient automaton.
    order = sorted(range(len(blocks)), key=lambda index: min(blocks[index]))
    number = dict((index, position) for position, index in enumerate(order))
    trans = []
    finals = set()
    for index in order:
        block = blocks[index]
        representative = min(block)
        row = {}
        for symbol in sigma:
            target = trans[representative].get(symbol) if False else None
            row[symbol] = target
        trans.append(row)
    return Dfa(trans, finals, 0)
